class PanelQuad
{
public:
    virtual ~PanelQuad();
    virtual void Init();
    virtual void TurnOn(bool on);
};

class CheatFrontEnd
{
private:
    char base_layout[0x160];
    void *sys;
    bool pq_indices_set;
    char pq_indices_padding[3];
    PanelQuad *arrow_up[2];
    PanelQuad *arrow_down[2];
    PanelQuad *cellphone;
    PanelQuad *numbers[10];
    PanelQuad *numbers_hi[10];

public:
    void SetPQIndices();
    void TurnOnPhone(bool on);
};

void CheatFrontEnd::TurnOnPhone(bool on)
{
	SetPQIndices();

	//Turn off the cell phone, etc
	arrow_up[0]->TurnOn(false);
	arrow_up[1]->TurnOn(false);
	arrow_down[0]->TurnOn(false);
	arrow_down[1]->TurnOn(false);
	cellphone->TurnOn(on);

	for(int i = 0; i < 10; i++)
	{
		numbers[i]->TurnOn(on);
		numbers_hi[i]->TurnOn(false);
	}
}
